/* Scheduling and operational follow-up UI. This remains a browser-local demo. */
const scheduleRules=EeroScheduling;
let scheduleView='agenda';
const agendaFilters={from:today(),to:'',status:'',therapistId:'',query:''};
const staffName=id=>state.staffDemo?.find(s=>s.id===id)?.name||'Unassigned';
function staffOptions(blank='All therapists'){return `<option value="">${blank}</option>`+(state.staffDemo||[]).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}
function scheduleMetricsHTML(){const m=scheduleRules.summary(state.appointments||[],today());return `<div class="schedule-metrics" aria-label="Schedule overview">${[[m.today,'Scheduled today','today'],[m.unassigned,'Upcoming unassigned','unassigned'],[m.needsAttendance,'Attendance to update','attendance'],[m.completed,'Completed sessions','completed']].map(([n,label,key])=>`<button class="schedule-metric" data-schedule-metric="${key}"><strong>${n}</strong><span>${label} →</span></button>`).join('')}</div>`}
function agendaRowsHTML(){const rows=scheduleRules.agenda(state.appointments||[],{...agendaFilters,cases:state.cases});return `<p class="muted" role="status">${rows.length} session${rows.length===1?'':'s'} match your filters. Times are local to this browser.</p>${rows.length?`<div class="agenda-list">${rows.map(a=>`<article class="agenda-row"><div class="agenda-date"><strong>${esc(a.date)}</strong><span>${esc(a.time)} · ${a.duration} min</span></div><div class="agenda-details"><h3>${esc(a.title)}</h3><p>${esc(state.cases.find(c=>c.id===a.caseId)?.label)} · ${esc(a.location)}</p><small>${esc(staffName(a.therapistId))}</small></div><span class="session-status status-${a.status.toLowerCase()}">${esc(a.status)}</span><button class="secondary" data-session="${esc(a.id)}" aria-label="Edit ${esc(a.title)}">Edit session</button></article>`).join('')}</div>`:`<div class="empty"><h3>No sessions match.</h3><p>Change your filters or plan a sample session.</p><button class="secondary" id="agenda-clear-empty">Clear filters</button></div>`}`}
function agendaHTML(){return `<section id="agenda-workspace" ${scheduleView==='month'?'hidden':''}><div class="panel-heading"><div><span class="tiny-label">STAFF / SCHEDULING</span><h2>Make space for the next step.</h2><p>Assign a therapist, avoid overlaps, and keep attendance up to date.</p></div><button class="primary" id="agenda-add">＋ Plan session</button></div><div class="agenda-filters"><label class="field">Search sessions<input type="search" id="agenda-query" maxlength="120" value="${esc(agendaFilters.query)}" placeholder="Session, case or location"></label><label class="field">From<input type="date" id="agenda-from" value="${esc(agendaFilters.from)}"></label><label class="field">Through<input type="date" id="agenda-to" value="${esc(agendaFilters.to)}"></label><label class="field">Therapist<select id="agenda-therapist">${staffOptions()}<option value="__unassigned__">Unassigned only</option></select></label><label class="field">Attendance<select id="agenda-status"><option value="">All statuses</option>${scheduleRules.statuses.map(s=>`<option>${s}</option>`).join('')}</select></label><button class="secondary" id="agenda-clear">Clear filters</button></div><p id="agenda-error" class="schedule-error" role="alert" hidden></p><div id="agenda-results">${agendaRowsHTML()}</div></section>`}
const monthCalendarHTML=calendarHTML;
calendarHTML=function(){return `<div class="schedule-heading"><div><span class="tiny-label">CARE OPERATIONS</span><h2>Your schedule, in focus.</h2></div><div class="schedule-tabs" aria-label="Schedule views"><button class="secondary" id="schedule-agenda" aria-pressed="${scheduleView==='agenda'}">Agenda</button><button class="secondary" id="schedule-month" aria-pressed="${scheduleView==='month'}">Month</button></div></div>${scheduleMetricsHTML()}${agendaHTML()}<section id="month-workspace" ${scheduleView==='agenda'?'hidden':''}>${monthCalendarHTML()}</section>`};
function clearAgendaFilters(){Object.assign(agendaFilters,{from:'',to:'',status:'',therapistId:'',query:''});render()}
function refreshAgenda(){const invalid=agendaFilters.from&&agendaFilters.to&&agendaFilters.to<agendaFilters.from;$('agenda-error').hidden=!invalid;$('agenda-error').textContent=invalid?'The end date must be on or after the start date.':'';$('agenda-results').innerHTML=invalid?'':agendaRowsHTML();if($('agenda-clear-empty'))$('agenda-clear-empty').onclick=clearAgendaFilters}
const operationsPriorRender=render;
render=function(){operationsPriorRender();if(currentView!=='calendar'||portalRole==='client')return;
  document.querySelectorAll('[data-schedule-metric]').forEach(b=>b.onclick=()=>{const key=b.dataset.scheduleMetric;Object.assign(agendaFilters,{from:'',to:'',status:'Scheduled',therapistId:'',query:''});if(key==='today'){agendaFilters.from=today();agendaFilters.to=today()}if(key==='unassigned'){agendaFilters.from=today();agendaFilters.therapistId='__unassigned__'}if(key==='attendance'){const day=new Date(today()+'T12:00:00Z');day.setUTCDate(day.getUTCDate()-1);agendaFilters.to=day.toISOString().slice(0,10)}if(key==='completed')agendaFilters.status='Completed';scheduleView='agenda';render()});
  $('schedule-agenda').onclick=()=>{scheduleView='agenda';render()};$('schedule-month').onclick=()=>{scheduleView='month';render()};$('agenda-add').onclick=()=>openSession();$('agenda-clear').onclick=clearAgendaFilters;
  $('agenda-therapist').value=agendaFilters.therapistId;$('agenda-status').value=agendaFilters.status;
  for(const [id,key] of [['agenda-query','query'],['agenda-from','from'],['agenda-to','to'],['agenda-therapist','therapistId'],['agenda-status','status']])$(id).addEventListener(key==='query'?'input':'change',e=>{agendaFilters[key]=e.target.value;refreshAgenda()});
  refreshAgenda();
  $('month-workspace').querySelectorAll('[data-session]').forEach(b=>{const a=scheduleRules.normalize(state.appointments.find(x=>x.id===b.dataset.session));b.classList.toggle('cancelled-session',a.status==='Cancelled');b.title=`${a.status} · ${a.duration} min · ${staffName(a.therapistId)}`});
};
$('session-time').closest('.form-grid').insertAdjacentHTML('afterend',`<div class="form-grid"><label class="field">Therapist<select id="session-therapist"><option value="">Unassigned</option></select></label><label class="field">Duration in minutes<input id="session-duration" type="number" min="15" max="240" step="1" required value="60"></label></div><label class="field">Attendance status<select id="session-status">${scheduleRules.statuses.map(s=>`<option>${s}</option>`).join('')}</select></label><p id="session-error" class="schedule-error" role="alert" hidden></p><details id="session-history"><summary>Session activity</summary><ol id="session-history-list"></ol></details>`);
const schedulingOpenSession=openSession;
openSession=function(id){schedulingOpenSession(id);const a=id?scheduleRules.normalize(state.appointments.find(x=>x.id===id)):null;$('session-therapist').innerHTML=staffOptions('Unassigned');$('session-therapist').value=a?.therapistId||'';$('session-duration').value=a?.duration||60;$('session-status').value=a?.status||'Scheduled';$('session-error').hidden=true;$('session-history').hidden=!a?.history?.length;$('session-history-list').innerHTML=(a?.history||[]).map(h=>`<li>${esc(h)}</li>`).join('')};
$('session-form').onsubmit=async e=>{e.preventDefault();if(!$('session-form').reportValidity())return;const submit=$('session-form').querySelector('button.primary');const old=state.appointments||[];submit.disabled=true;$('session-error').hidden=true;
  try{const a=scheduleRules.validate({id:editingSession||uid(),caseId:$('session-case').value,title:$('session-title').value,date:$('session-date').value,time:$('session-time').value,location:$('session-location').value,therapistId:$('session-therapist').value,duration:Number($('session-duration').value),status:$('session-status').value});
    if(!state.cases.some(c=>c.id===a.caseId))throw Error('Choose an existing case folder.');
    if(a.therapistId&&!state.staffDemo.some(s=>s.id===a.therapistId))throw Error('Choose an existing therapist.');
    if(scheduleRules.conflicts(a,old).length)throw Error('This case or therapist already has a session at that time. Choose another time or cancel the overlapping session.');
    const prior=old.find(x=>x.id===a.id);a.history=[...(prior?.history||[]),`${prior?'Updated':'Created'} ${new Date().toLocaleString()} · ${a.status} · ${a.duration} minutes`];
    state.appointments=prior?old.map(x=>x.id===a.id?a:x):[...old,a];
    try{await persist()}catch{state.appointments=old;render();throw Error('Could not save the session. Check browser storage and try again.')}
    sessionDialog.close();toast('Sample session saved.');
  }catch(error){$('session-error').textContent=error.message;$('session-error').hidden=false}finally{submit.disabled=false}
};
// Preserve the scheduling history: cancellations replace destructive deletion.
$('session-delete').textContent='Cancel session';
$('session-delete').onclick=()=>{$('session-status').value='Cancelled';$('session-form').requestSubmit()};
if(state)render();
